"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import { Bar, BarChart, CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { ArrowLeft, Check, ChevronDown, Clipboard, Dices, FileText, GitCompareArrows, Info, LockKeyhole, Play, RotateCcw, Save, Send, ShieldCheck, SlidersHorizontal, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/components/auth/auth-provider";
import { usePersistentState } from "@/lib/hooks/use-persistent-state";
import { saveModelRun } from "@/lib/supabase/data";
import { arenaProgressKey, emptyArenaProgress, type ArenaProgress } from "@/components/mechanism-arena/mechanism-library";
import { mechanismPath, type MechanismScenario } from "@/lib/mechanism-arena/catalog";
import { bidForStrategy, defaultAuctionParameters, prepareBotBids, runRepeatedAuctionTrials, settleAuction, valuesFromSeed, type AuctionMode, type AuctionParameters, type AuctionResult, type BotStrategy, type RepeatedAuctionSummary, type ValueDistribution } from "@/lib/mechanism-arena/auction-engine";

type ExperimentStage = "understand" | "configure" | "act" | "settle" | "analyse";
type ExperimentStatus = "Not Started" | "Configuring" | "Awaiting Action" | "Actions Confirmed" | "Settling" | "Completed" | "Replaying" | "Comparing" | "Failed";
type AnalysisTab = "results" | "strategy" | "compare" | "trials" | "reflection";
type AuctionDraft = {
  mode: AuctionMode;
  stage: ExperimentStage;
  status: ExperimentStatus;
  seed: number;
  parameters: AuctionParameters;
  controlledBidder: number | null;
  values: number[];
  bids: number[];
  manualBid: number;
  submitted: boolean;
  confirmed: boolean;
  result: AuctionResult | null;
  comparison: AuctionResult | null;
  reflection: string;
  savedRunId?: string;
};

const stages: Array<{ id: ExperimentStage; label: string }> = [
  { id: "understand", label: "Understand" }, { id: "configure", label: "Configure" }, { id: "act", label: "Act" }, { id: "settle", label: "Settle" }, { id: "analyse", label: "Analyse" },
];
const strategyLabels: Record<BotStrategy, string> = { equilibrium: "Equilibrium Shading", truthful: "Truthful", conservative: "Conservative", aggressive: "Aggressive", random: "Random Within Bounds" };
const distributionLabels: Record<ValueDistribution, string> = { uniform: "Uniform", "low-value": "Low-Value Concentrated", "high-value": "High-Value Concentrated" };
const format = (value: number, digits = 2) => new Intl.NumberFormat("en-US", { maximumFractionDigits: digits }).format(value);
const initialDraft = (): AuctionDraft => ({ mode: "observe", stage: "understand", status: "Not Started", seed: 24031, parameters: { ...defaultAuctionParameters }, controlledBidder: null, values: [], bids: [], manualBid: 0, submitted: false, confirmed: false, result: null, comparison: null, reflection: "" });

export function AuctionExperimentWorkspace({ scenario }: { scenario: MechanismScenario }) {
  const isSecondPrice = scenario.scenario_id === "MA-02-SECOND-PRICE";
  const { user, openAuth } = useAuth();
  const [draft, setDraft, hydrated] = usePersistentState<AuctionDraft>(`econmind:mechanism-arena:${scenario.scenario_id}:v3`, initialDraft());
  const [progress, setProgress, progressHydrated] = usePersistentState<ArenaProgress>(arenaProgressKey, emptyArenaProgress);
  const [analysisTab, setAnalysisTab] = useState<AnalysisTab>("results");
  const [saveStatus, setSaveStatus] = useState("Local draft");
  const [saveError, setSaveError] = useState("");
  const [isSettling, setIsSettling] = useState(false);
  const [trials, setTrials] = useState<RepeatedAuctionSummary | null>(null);

  const update = (partial: Partial<AuctionDraft> | ((current: AuctionDraft) => Partial<AuctionDraft>)) => setDraft((current) => ({ ...current, ...(typeof partial === "function" ? partial(current) : partial) }));
  const currentRule = isSecondPrice ? "second-price" as const : "first-price" as const;
  const strategies = useMemo(() => Array.from({ length: draft.parameters.bidderCount }, (_, index) => index + 1 === draft.controlledBidder ? "manual" as const : draft.parameters.sharedBotStrategy), [draft.controlledBidder, draft.parameters.bidderCount, draft.parameters.sharedBotStrategy]);
  const canRun = draft.values.length === draft.parameters.bidderCount && (draft.mode === "observe" || draft.confirmed);
  const activeIndex = stages.findIndex((item) => item.id === draft.stage);

  useEffect(() => {
    if (!hydrated || !progressHydrated) return;
    setProgress((current) => ({ ...current, opened: { ...current.opened, [scenario.scenario_id]: new Date().toISOString() } }));
  // A route visit is intentionally recorded only in browser progress; runs save separately on request.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hydrated, progressHydrated, scenario.scenario_id]);

  useEffect(() => {
    if (new URLSearchParams(window.location.search).get("mode") !== "compare") return;
    setDraft((current) => current.mode === "compare" ? current : { ...current, mode: "compare", status: "Comparing" });
  }, [setDraft]);

  useEffect(() => {
    if (!draft.result || !progressHydrated) return;
    setProgress((current) => current.completed.includes(scenario.scenario_id) ? current : { ...current, completed: [...current.completed, scenario.scenario_id] });
  }, [draft.result, progressHydrated, scenario.scenario_id, setProgress]);

  function setMode(mode: AuctionMode) {
    const controlledBidder = mode === "play" ? Math.min(draft.controlledBidder ?? 1, draft.parameters.bidderCount) : null;
    update({ mode, controlledBidder, stage: draft.stage === "understand" ? "configure" : draft.stage, status: mode === "compare" ? "Comparing" : "Configuring", result: null, comparison: null, submitted: false, confirmed: false });
  }

  function changeParameters(partial: Partial<AuctionParameters>) {
    const parameters = { ...draft.parameters, ...partial };
    const controlledBidder = draft.mode === "play" ? Math.min(draft.controlledBidder ?? 1, parameters.bidderCount) : null;
    update({ parameters, controlledBidder, values: [], bids: [], submitted: false, confirmed: false, result: null, comparison: null, stage: "configure", status: "Configuring" });
  }

  function drawValues() {
    const values = valuesFromSeed(draft.seed, draft.parameters);
    const bids = prepareBotBids(draft.seed, values, draft.parameters, strategies);
    const controlledIndex = (draft.controlledBidder ?? 1) - 1;
    update({ values, bids, manualBid: draft.mode === "play" ? Math.min(values[controlledIndex], bids[controlledIndex] || values[controlledIndex]) : 0, submitted: false, confirmed: false, result: null, comparison: null, stage: "act", status: draft.mode === "play" ? "Awaiting Action" : "Actions Confirmed" });
    setAnalysisTab("results");
  }

  function submitBid() {
    if (!draft.controlledBidder || !draft.values.length) return;
    const maximum = draft.parameters.allowOverbidding ? draft.values[draft.controlledBidder - 1] * 1.25 : draft.values[draft.controlledBidder - 1];
    const bid = Math.min(Math.max(0, Number.isFinite(draft.manualBid) ? draft.manualBid : 0), maximum);
    const bids = [...draft.bids];
    bids[draft.controlledBidder - 1] = Math.round(bid * 100) / 100;
    update({ bids, manualBid: bid, submitted: true, status: "Awaiting Action" });
  }

  function confirmBid() {
    if (!draft.submitted) return;
    update({ confirmed: true, status: "Actions Confirmed" });
  }

  function settle() {
    if (!canRun || isSettling) return;
    const completeSettlement = () => {
      try {
        const first = settleAuction({ rule: currentRule, values: draft.values, bids: draft.bids, strategies });
        const comparison = draft.mode === "compare" ? settleAuction({ rule: currentRule === "first-price" ? "second-price" : "first-price", values: draft.values, bids: draft.bids, strategies }) : null;
        update({ result: first, comparison, stage: "analyse", status: draft.mode === "compare" ? "Comparing" : "Completed" });
        if (comparison) setProgress((current) => current.compared.includes(scenario.scenario_id) ? current : { ...current, compared: [...current.compared, scenario.scenario_id] });
      } catch {
        update({ status: "Failed" });
      } finally { setIsSettling(false); }
    };
    update({ stage: "settle", status: "Settling" });
    setIsSettling(true);
    const reducedMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    window.setTimeout(completeSettlement, reducedMotion ? 0 : 450);
  }

  function reset() {
    setDraft(initialDraft());
    setTrials(null);
    setSaveStatus("Local draft reset");
    setSaveError("");
  }

  function replay() {
    if (!draft.result) return;
    update({ stage: "analyse", status: "Replaying" });
    window.setTimeout(() => update({ stage: "analyse", status: draft.mode === "compare" ? "Comparing" : "Completed" }), 120);
  }

  function newSeed() {
    const next = Math.floor((Date.now() % 900000) + 100000);
    update({ seed: next, values: [], bids: [], result: null, comparison: null, submitted: false, confirmed: false, stage: "configure", status: "Configuring" });
  }

  async function copySeed() {
    try { await navigator.clipboard.writeText(String(draft.seed)); setSaveStatus("Seed copied"); } catch { setSaveStatus("Copy the displayed seed manually"); }
  }

  async function saveDraft() {
    if (!user) { openAuth("sign-in"); return; }
    setSaveError("");
    setSaveStatus("Saving…");
    try {
      const row = await saveModelRun({
        userId: user.id,
        modelKey: "mechanism-arena",
        name: `${scenario.title} · ${draft.status}`.slice(0, 120),
        parameters: { scenario_id: scenario.scenario_id, scenario_version: "1.0.0", seed: draft.seed, mode: draft.mode, parameters: draft.parameters, controlled_bidder: draft.controlledBidder, submitted_actions: draft.bids, reflection: draft.reflection },
        results: draft.result ? { allocation: draft.result.winnerId, payment: draft.result.payment, payoffs: draft.result.participants.map((participant) => participant.payoff), metrics: draft.result } : {},
        metadata: { arena: true, status: draft.status, comparison: draft.comparison, saved_at: new Date().toISOString() },
      });
      update({ savedRunId: row.id });
      setSaveStatus("Saved privately");
    } catch (caught) { setSaveError(caught instanceof Error ? caught.message : "Could not save this experiment."); setSaveStatus("Save failed"); }
  }

  function runTrials(count: 10 | 50 | 100) {
    setTrials(runRepeatedAuctionTrials({ seed: draft.seed, parameters: draft.parameters, strategy: draft.parameters.sharedBotStrategy, count }));
    setAnalysisTab("trials");
  }

  if (!hydrated) return <main className="mx-auto min-h-screen max-w-[1440px] px-5 py-10 sm:px-8 lg:px-12"><p className="text-sm text-[var(--ink-muted)]">Loading your local experiment draft…</p></main>;

  return <main className="mechanism-workspace-live mx-auto min-h-screen max-w-[1440px] px-5 py-7 sm:px-8 lg:px-12 lg:py-9">
    <header className="border-b border-[var(--line)] pb-5"><div className="flex flex-wrap items-center justify-between gap-3"><Link href="/mechanism-arena" className="inline-flex items-center gap-1.5 text-xs font-bold text-[var(--ink-muted)] hover:text-[var(--ink)]"><ArrowLeft size={14} /> Back to Mechanism Library</Link><div className="flex flex-wrap items-center gap-2"><Badge>{scenario.category}</Badge><Badge>{scenario.difficulty}</Badge><Badge className="normal-case tracking-normal">Fixed seed {draft.seed}</Badge><Badge className={saveStatus === "Saved privately" ? "bg-[var(--accent-soft)] text-[var(--accent)]" : ""}>{saveStatus}</Badge></div></div><div className="mt-5 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-[10px] font-extrabold uppercase tracking-[.14em] text-[var(--accent)]">Mechanism {String(scenario.number).padStart(2, "0")} · {scenario.scenario_id}</p><h1 className="mt-2 text-3xl font-bold tracking-[-.05em] sm:text-4xl">{scenario.title}</h1><p className="mt-3 max-w-3xl text-sm leading-6 text-[var(--ink-muted)]">Explore how private information and payment rules create incentives for bid shading.</p></div><div className="flex flex-wrap gap-2"><Button variant="secondary" size="sm" onClick={reset}><RotateCcw size={14} /> Reset experiment</Button><Button variant="secondary" size="sm" disabled={!draft.result} onClick={replay}><Play size={14} /> Replay previous run</Button><Button size="sm" onClick={() => void saveDraft()}><Save size={14} /> {user ? "Save draft" : "Sign in to save"}</Button></div></div></header>

    <ExperimentProgress stages={stages} activeIndex={activeIndex} status={draft.status} />

    <div className="mt-6 grid gap-5 xl:grid-cols-12 xl:items-start"><aside className="xl:sticky xl:top-20 xl:col-span-3"><RulesPanel /></aside><section className="min-w-0 xl:col-span-6"><ExperimentStage draft={draft} scenario={scenario} strategies={strategies} currentRule={currentRule} isSettling={isSettling} onConfigure={() => update({ stage: "configure", status: "Configuring" })} onDraw={drawValues} onManualBid={(manualBid) => update({ manualBid, submitted: false, confirmed: false, status: "Awaiting Action" })} onSubmit={submitBid} onConfirm={confirmBid} onSettle={settle} onAnalyse={() => update({ stage: "analyse", status: draft.mode === "compare" ? "Comparing" : "Completed" })} /></section><aside className="xl:sticky xl:top-20 xl:col-span-3"><ConfigurationPanel draft={draft} scenario={scenario} onMode={setMode} onChangeParameters={changeParameters} onControlledBidder={(controlledBidder) => update({ controlledBidder, values: [], bids: [], submitted: false, confirmed: false, result: null, comparison: null, stage: "configure", status: "Configuring" })} onSeed={newSeed} onCopy={copySeed} /></aside></div>

    {draft.result && <AnalysisDashboard draft={draft} scenario={scenario} tab={analysisTab} trials={trials} onTab={setAnalysisTab} onTrials={runTrials} onReflection={(reflection) => update({ reflection })} onRunSame={() => { update({ values: [], bids: [], submitted: false, confirmed: false, result: null, comparison: null, stage: "act", status: draft.mode === "play" ? "Awaiting Action" : "Actions Confirmed" }); drawValues(); }} onRunNew={newSeed} onPrint={() => window.print()} />}
    {saveError && <p role="alert" className="mt-5 rounded-lg bg-[var(--red-soft)] p-3 text-sm text-[var(--red)]">{saveError}</p>}
    <ExperimentReport scenario={scenario} draft={draft} />
  </main>;
}

function ExperimentProgress({ stages, activeIndex, status }: { stages: Array<{ id: ExperimentStage; label: string }>; activeIndex: number; status: ExperimentStatus }) { return <div className="mt-5 rounded-xl border border-[var(--line)] bg-[var(--surface)] p-3 sm:p-4"><div className="flex items-center justify-between gap-3"><p className="text-xs font-bold">Experiment progress</p><span className="text-[11px] font-semibold text-[var(--accent)]">{status}</span></div><ol className="mt-3 grid grid-cols-5 gap-1">{stages.map((stage, index) => <li key={stage.id} aria-current={index === activeIndex ? "step" : undefined} className={`rounded-lg px-2 py-2 text-center text-[10px] font-bold sm:text-xs ${index === activeIndex ? "bg-[var(--accent)] text-white" : index < activeIndex ? "bg-[var(--accent-soft)] text-[var(--accent)]" : "bg-[var(--surface-subtle)] text-[var(--ink-faint)]"}`}><span className="mr-1 opacity-80">{index + 1}</span>{stage.label}</li>)}</ol></div>; }

function RulesPanel() { const [open, setOpen] = useState<Record<string, boolean>>({ environment: true, participants: true, information: true, actions: false, allocation: false, payoff: false, question: true }); return <section className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-4"><p className="text-[10px] font-extrabold uppercase tracking-[.14em] text-[var(--accent)]">Rules briefing</p><h2 className="mt-2 text-lg font-bold">First-Price Auction</h2><div className="mt-4 space-y-1"><RuleSection title="Environment" open={open.environment} onToggle={() => setOpen((current) => ({ ...current, environment: !current.environment }))}>One indivisible item is offered for sale. Several bidders independently receive private valuations and submit sealed bids.</RuleSection><RuleSection title="Participants" open={open.participants} onToggle={() => setOpen((current) => ({ ...current, participants: !current.participants }))}>One seller and two to eight bidders. The default setting contains three bidders.</RuleSection><RuleSection title="Information" open={open.information} onToggle={() => setOpen((current) => ({ ...current, information: !current.information }))}><ul className="space-y-2"><li><Visibility label="Private" /> Each bidder knows their own value and submitted bid.</li><li><Visibility label="Hidden until settlement" /> Other values and sealed bids are unavailable before the auction closes.</li><li><Visibility label="Public" /> The allocation and payment rules are known to everyone.</li></ul></RuleSection><RuleSection title="Allowed actions" open={open.actions} onToggle={() => setOpen((current) => ({ ...current, actions: !current.actions }))}>Submit one sealed non-negative bid, revise before confirmation, then confirm it. No further action is available after confirmation.</RuleSection><RuleSection title="Allocation and payment" open={open.allocation} onToggle={() => setOpen((current) => ({ ...current, allocation: !current.allocation }))}>The highest bid wins. Bid ties use the lowest bidder ID. The winner pays their own bid; losing bidders pay zero.</RuleSection><RuleSection title="Payoff rule" open={open.payoff} onToggle={() => setOpen((current) => ({ ...current, payoff: !current.payoff }))}><div className="space-y-2 text-sm"><MathLine label="Winner payoff" content={<><i>u</i><sub>i</sub> = <i>v</i><sub>i</sub> − <i>b</i><sub>i</sub></>} /><MathLine label="Losing bidder payoff" content={<><i>u</i><sub>i</sub> = 0</>} /><MathLine label="Seller revenue" content={<><i>R</i> = max(<i>b</i><sub>1</sub>, …, <i>b</i><sub>n</sub>)</>} /></div></RuleSection><RuleSection title="Strategic question" open={open.question} onToggle={() => setOpen((current) => ({ ...current, question: !current.question }))}>Should a bidder submit their full private value or shade the bid below it?</RuleSection></div></section>; }
function RuleSection({ title, open, onToggle, children }: { title: string; open: boolean; onToggle: () => void; children: React.ReactNode }) { return <div className="border-b border-[var(--line)] py-3 last:border-0"><button type="button" onClick={onToggle} aria-expanded={open} className="flex w-full items-center justify-between gap-3 text-left text-xs font-bold"><span>{title}</span><ChevronDown size={14} className={open ? "rotate-180 transition" : "transition"} /></button>{open && <div className="mt-2 text-xs leading-5 text-[var(--ink-muted)]">{children}</div>}</div>; }
function Visibility({ label }: { label: string }) { return <span className="mr-1 inline-flex rounded border border-[var(--line-strong)] bg-[var(--canvas)] px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-[var(--ink)]">{label}</span>; }
function MathLine({ label, content }: { label: string; content: React.ReactNode }) { return <p><span className="mr-2 text-[10px] font-bold uppercase tracking-wide text-[var(--ink-faint)]">{label}</span><span aria-label={label}>{content}</span></p>; }

function ConfigurationPanel({ draft, scenario, onMode, onChangeParameters, onControlledBidder, onSeed, onCopy }: { draft: AuctionDraft; scenario: MechanismScenario; onMode: (mode: AuctionMode) => void; onChangeParameters: (partial: Partial<AuctionParameters>) => void; onControlledBidder: (value: number) => void; onSeed: () => void; onCopy: () => void }) { return <section className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-4"><p className="text-[10px] font-extrabold uppercase tracking-[.14em] text-[var(--accent)]">Experiment configuration</p><h2 className="mt-2 text-lg font-bold">Permitted controls</h2><div className="mt-4 space-y-5"><fieldset><legend className="text-xs font-bold">Experiment mode</legend><div className="mt-2 grid gap-2">{(["observe", "play", "compare"] as const).map((mode) => <button key={mode} type="button" onClick={() => onMode(mode)} className={`rounded-lg border p-2.5 text-left text-xs ${draft.mode === mode ? "border-[var(--accent)] bg-[var(--accent-soft)] text-[var(--accent)]" : "border-[var(--line)] bg-[var(--canvas)] text-[var(--ink-muted)]"}`}><strong className="capitalize">{mode} mode</strong><span className="mt-1 block leading-4">{mode === "observe" ? "Preset strategies; observe the rule." : mode === "play" ? "Control one bidder; others are bots." : "Matched values and bids under two rules."}</span></button>)}</div></fieldset><RangeControl label="Bidder Count" value={draft.parameters.bidderCount} min={2} max={8} step={1} unit="bidders" defaultValue={3} explanation="More bidders increase competition and may increase expected seller revenue." onChange={(value) => onChangeParameters({ bidderCount: Math.round(value) })} /><RangeControl label="Maximum Private Value" value={draft.parameters.maxValue} min={10} max={500} step={10} unit="GCU" defaultValue={100} explanation="Defines the upper bound of the private-value distribution." onChange={(value) => onChangeParameters({ maxValue: value })} /><label className="block text-xs font-bold">Value distribution<select value={draft.parameters.distribution} onChange={(event) => onChangeParameters({ distribution: event.target.value as ValueDistribution })} className="mt-2 h-10 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-sm font-normal outline-none focus:border-[var(--accent)]">{Object.entries(distributionLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><span className="mt-1 block text-[10px] font-normal leading-4 text-[var(--ink-muted)]">Controlled presets preserve a documented distribution.</span></label>{draft.mode === "play" && <label className="block text-xs font-bold">Student role<select value={draft.controlledBidder ?? 1} onChange={(event) => onControlledBidder(Number(event.target.value))} className="mt-2 h-10 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-sm font-normal outline-none focus:border-[var(--accent)]">{Array.from({ length: draft.parameters.bidderCount }, (_, index) => <option key={index + 1} value={index + 1}>Control Bidder {index + 1}</option>)}</select></label>}<label className="block text-xs font-bold">Bot strategy<select value={draft.parameters.sharedBotStrategy} onChange={(event) => onChangeParameters({ sharedBotStrategy: event.target.value as BotStrategy })} className="mt-2 h-10 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-sm font-normal outline-none focus:border-[var(--accent)]">{Object.entries(strategyLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><span className="mt-1 block text-[10px] font-normal leading-4 text-[var(--ink-muted)]">One disclosed shared strategy applies to all bots.</span></label><label className="flex items-start gap-2 text-xs leading-5 text-[var(--ink-muted)]"><input type="checkbox" checked={draft.parameters.allowOverbidding} onChange={(event) => onChangeParameters({ allowOverbidding: event.target.checked })} className="mt-1 accent-[var(--accent)]"/><span><strong className="text-[var(--ink)]">Allow overbidding</strong><br />Off by default to keep the basic loss-risk lesson controlled.</span></label><div className="rounded-lg border border-[var(--line)] bg-[var(--canvas)] p-3"><p className="text-xs font-bold">Fixed Seed: {draft.seed}</p><p className="mt-1 text-[10px] leading-4 text-[var(--ink-muted)]">Every saved run records its seed, parameters, strategies and submitted actions.</p><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" variant="secondary" onClick={onSeed}><Dices size={13} /> Draw new</Button><Button size="sm" variant="secondary" onClick={() => void onCopy()}><Clipboard size={13} /> Copy</Button></div></div></div></section>; }
function RangeControl({ label, value, min, max, step, unit, defaultValue, explanation, onChange }: { label: string; value: number; min: number; max: number; step: number; unit: string; defaultValue: number; explanation: string; onChange: (value: number) => void }) { return <div><div className="flex items-start justify-between gap-2"><label className="text-xs font-bold">{label}</label><output className="rounded bg-[var(--accent-soft)] px-2 py-1 text-xs font-bold text-[var(--accent)]">{format(value, 0)} {unit}</output></div><input aria-label={label} type="range" min={min} max={max} step={step} value={value} onChange={(event) => onChange(Number(event.target.value))} className="mt-3 w-full"/><div className="flex justify-between text-[10px] text-[var(--ink-faint)]"><span>Min {min}</span><span>Max {max}</span></div><p className="mt-1 text-[10px] leading-4 text-[var(--ink-muted)]">Default {defaultValue} {unit}. {explanation}</p></div>; }

function ExperimentStage({ draft, scenario, strategies, currentRule, isSettling, onConfigure, onDraw, onManualBid, onSubmit, onConfirm, onSettle, onAnalyse }: { draft: AuctionDraft; scenario: MechanismScenario; strategies: Array<BotStrategy | "manual">; currentRule: "first-price" | "second-price"; isSettling: boolean; onConfigure: () => void; onDraw: () => void; onManualBid: (value: number) => void; onSubmit: () => void; onConfirm: () => void; onSettle: () => void; onAnalyse: () => void }) {
  const userValue = draft.controlledBidder ? draft.values[draft.controlledBidder - 1] : 0;
  const maxBid = draft.parameters.allowOverbidding ? userValue * 1.25 : userValue;
  return <section className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-4 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[10px] font-extrabold uppercase tracking-[.14em] text-[var(--accent)]">Experiment stage</p><h2 className="mt-1 text-xl font-bold">{draft.stage === "understand" ? "Understand the mechanism" : draft.stage === "configure" ? "Confirm the controlled environment" : draft.stage === "act" ? "Participants and sealed actions" : draft.stage === "settle" ? "Settlement" : "Analyse the result"}</h2></div><Badge className="normal-case tracking-normal">{currentRule === "first-price" ? "Winner pays own bid" : "Winner pays second-highest bid"}</Badge></div>
    {draft.stage === "understand" && <div className="mt-6"><MechanismFlow /><p className="mt-6 text-sm leading-6 text-[var(--ink-muted)]">Private values are drawn deterministically from the displayed seed. Each bidder acts without observing rivals’ values or bids.</p><Button className="mt-5" onClick={onConfigure}>Continue to configuration <ArrowLeft className="rotate-180" size={14} /></Button></div>}
    {draft.stage === "configure" && <div className="mt-6"><div className="rounded-xl bg-[var(--surface-subtle)] p-5"><p className="text-sm font-bold">Ready to draw private values</p><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">The current environment has {draft.parameters.bidderCount} bidders, a {distributionLabels[draft.parameters.distribution].toLowerCase()} value distribution, and a maximum value of {format(draft.parameters.maxValue, 0)} GCU.</p><p className="mt-3 text-xs text-[var(--ink-faint)]">{draft.mode === "play" ? "You will see only your own private value after values are drawn." : "All participant values will remain hidden until settlement."}</p></div><Button className="mt-5" onClick={onDraw}><Dices size={15} /> Draw values</Button></div>}
    {draft.stage === "act" && <div className="mt-6"><ParticipantTable draft={draft} strategies={strategies} /><div className="mt-5">{draft.mode === "play" ? <ActionInput value={userValue} bid={draft.manualBid} maxBid={maxBid} submitted={draft.submitted} confirmed={draft.confirmed} onBid={onManualBid} onSubmit={onSubmit} onConfirm={onConfirm} /> : <ObserveAction draft={draft} />}</div><RunControls draft={draft} onSettle={onSettle} /></div>}
    {draft.stage === "settle" && <div className="mt-8"><div className="rounded-xl border border-[var(--accent)] bg-[var(--accent-soft)] p-6 text-center"><ShieldCheck className={`mx-auto text-[var(--accent)] ${isSettling ? "animate-pulse" : ""}`} size={32} /><h3 className="mt-3 text-lg font-bold">Bidding closes and settlement begins</h3><ol className="mx-auto mt-4 max-w-md space-y-2 text-left text-sm text-[var(--ink-muted)]"><li>1. Sealed bids are revealed.</li><li>2. Bids are ranked using the fixed bidder-ID tie-break.</li><li>3. The winner, payment and each payoff are calculated.</li></ol></div></div>}
    {draft.stage === "analyse" && <div className="mt-6 rounded-xl border border-[var(--accent)] bg-[var(--accent-soft)] p-5"><p className="flex items-center gap-2 text-sm font-bold text-[var(--accent)]"><Check size={16} /> Settlement complete</p><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">Every private value and sealed bid can now be inspected in the result dashboard below.</p><Button className="mt-4" onClick={onAnalyse}>Inspect analysis <ArrowLeft className="rotate-180" size={14} /></Button></div>}
  </section>;
}
function MechanismFlow() { const flow = ["Private values drawn", "Sealed bids submitted", "Bids ranked", "Highest bidder selected", "Payment calculated", "Payoffs calculated"]; return <ol className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{flow.map((step, index) => <li key={step} className="rounded-lg border border-[var(--line)] bg-[var(--canvas)] p-3 text-sm"><span className="mr-2 text-xs font-bold text-[var(--accent)]">{index + 1}</span>{step}</li>)}</ol>; }
function ParticipantTable({ draft, strategies }: { draft: AuctionDraft; strategies: Array<BotStrategy | "manual"> }) { return <div className="overflow-hidden rounded-xl border border-[var(--line)]"><table className="w-full text-left text-xs"><thead className="bg-[var(--surface-subtle)] text-[10px] uppercase tracking-wide text-[var(--ink-faint)]"><tr><th className="p-3">Participant</th><th className="p-3">Role</th><th className="p-3">Private value</th><th className="p-3">Strategy</th><th className="p-3">Status</th></tr></thead><tbody><tr className="border-t border-[var(--line)]"><td className="p-3 font-bold">Seller</td><td className="p-3">Seller</td><td className="p-3">—</td><td className="p-3">Fixed settlement rule</td><td className="p-3">Waiting</td></tr>{Array.from({ length: draft.parameters.bidderCount }, (_, index) => { const student = draft.controlledBidder === index + 1; return <tr key={index} className="border-t border-[var(--line)]"><td className="p-3 font-bold">Bidder {index + 1}</td><td className="p-3">{student ? "Student" : "Bot"}</td><td className="p-3">{student ? `${format(draft.values[index], 0)} GCU` : <span className="text-[var(--ink-muted)]"><LockKeyhole className="mr-1 inline" size={11} />Hidden</span>}</td><td className="p-3">{student ? "Manual bid" : strategyLabels[strategies[index] as BotStrategy]}</td><td className="p-3">{student ? draft.confirmed ? "Bid sealed" : draft.submitted ? "Ready to confirm" : "Action required" : "Ready"}</td></tr>; })}</tbody></table></div>; }
function ActionInput({ value, bid, maxBid, submitted, confirmed, onBid, onSubmit, onConfirm }: { value: number; bid: number; maxBid: number; submitted: boolean; confirmed: boolean; onBid: (value: number) => void; onSubmit: () => void; onConfirm: () => void }) { const potential = Math.max(0, value - bid); return <section className="rounded-xl border border-[var(--accent)] bg-[var(--accent-soft)] p-5"><p className="text-[10px] font-extrabold uppercase tracking-[.13em] text-[var(--accent)]">Your sealed action</p><div className="mt-3 grid gap-4 sm:grid-cols-2"><div><p className="text-xs font-bold text-[var(--ink-muted)]">Your private value</p><p className="mt-1 text-3xl font-bold tracking-[-.05em]">{format(value, 0)} <span className="text-sm text-[var(--ink-faint)]">GCU</span></p></div><div><p className="text-xs font-bold text-[var(--ink-muted)]">Potential surplus if you win</p><p className="mt-1 text-3xl font-bold tracking-[-.05em]">{format(potential)} <span className="text-sm text-[var(--ink-faint)]">GCU</span></p></div></div><label className="mt-5 block text-xs font-bold">Your bid <span className="font-normal text-[var(--ink-muted)]">(0–{format(maxBid)} GCU)</span><div className="mt-2 flex gap-2"><input aria-label="Your bid in GCU" type="number" min="0" max={maxBid} step="0.01" disabled={confirmed} value={bid} onChange={(event) => onBid(Number(event.target.value))} className="h-10 min-w-0 flex-1 rounded-lg border border-[var(--line-strong)] bg-[var(--surface)] px-3 text-sm outline-none focus:border-[var(--accent)] disabled:opacity-70"/><span className="inline-flex h-10 items-center rounded-lg bg-[var(--surface)] px-3 text-xs text-[var(--ink-muted)]">GCU</span></div><input aria-label="Adjust bid" type="range" min="0" max={maxBid} step="0.5" disabled={confirmed} value={bid} onChange={(event) => onBid(Number(event.target.value))} className="mt-3 w-full"/></label><div className="mt-5 flex flex-wrap gap-2"><Button variant="secondary" disabled={confirmed} onClick={() => onBid(value * (2 / 3))}><RotateCcw size={14} /> Reset benchmark</Button><Button disabled={confirmed} onClick={onSubmit}><Send size={14} /> Submit bid</Button><Button disabled={!submitted || confirmed} onClick={onConfirm}><LockKeyhole size={14} /> {confirmed ? "Bid sealed" : "Confirm bid"}</Button></div>{confirmed && <p className="mt-3 flex items-center gap-1.5 text-xs font-bold text-[var(--accent)]"><LockKeyhole size={13} /> Bid sealed. Other bids remain hidden until settlement.</p>}</section>; }
function ObserveAction({ draft }: { draft: AuctionDraft }) { return <section className="rounded-xl border border-[var(--line)] bg-[var(--canvas)] p-5"><Sparkles className="text-[var(--accent)]" size={18} /><h3 className="mt-3 text-sm font-bold">Observe Mode: preset strategies are ready</h3><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">Bots use the disclosed strategy selected in Experiment Configuration. Their values and bids remain hidden until settlement.</p><p className="mt-3 text-xs font-bold text-[var(--accent)]">{draft.status === "Actions Confirmed" ? "All bot actions confirmed." : "Actions are ready to settle."}</p></section>; }
function RunControls({ draft, onSettle }: { draft: AuctionDraft; onSettle: () => void }) { const explanation = draft.mode === "play" && !draft.confirmed ? "Submit and confirm your bid before running the mechanism." : "All required actions are confirmed."; return <div className="mt-5 flex flex-col gap-3 rounded-xl border border-[var(--line)] bg-[var(--surface-subtle)] p-4 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs leading-5 text-[var(--ink-muted)]">{explanation}</p><Button disabled={draft.mode === "play" && !draft.confirmed} onClick={onSettle}><Play size={15} /> Run mechanism</Button></div>; }

function AnalysisDashboard({ draft, scenario, tab, trials, onTab, onTrials, onReflection, onRunSame, onRunNew, onPrint }: { draft: AuctionDraft; scenario: MechanismScenario; tab: AnalysisTab; trials: RepeatedAuctionSummary | null; onTab: (tab: AnalysisTab) => void; onTrials: (count: 10 | 50 | 100) => void; onReflection: (reflection: string) => void; onRunSame: () => void; onRunNew: () => void; onPrint: () => void }) { const result = draft.result!; return <section className="mt-7"><div className="flex flex-col justify-between gap-4 border-t border-[var(--line)] pt-7 sm:flex-row sm:items-end"><div><p className="text-[10px] font-extrabold uppercase tracking-[.14em] text-[var(--accent)]">Results and analysis</p><h2 className="mt-2 text-2xl font-bold tracking-[-.04em]">Inspect allocation, payoffs and strategy</h2></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="secondary" onClick={onRunSame}><RotateCcw size={14} /> Same seed</Button><Button size="sm" variant="secondary" onClick={onRunNew}><Dices size={14} /> New seed</Button><Button size="sm" variant="secondary" onClick={onPrint}><FileText size={14} /> Print report</Button></div></div><div className="mt-5 flex gap-2 overflow-x-auto border-b border-[var(--line)] pb-2">{(["results", "strategy", "compare", "trials", "reflection"] as const).map((item) => <button key={item} type="button" onClick={() => onTab(item)} className={`min-h-9 whitespace-nowrap rounded-md px-3 text-xs font-bold capitalize ${tab === item ? "bg-[var(--accent)] text-white" : "bg-[var(--surface-subtle)] text-[var(--ink-muted)]"}`}>{item === "trials" ? "Repeated trials" : item}</button>)}</div>{tab === "results" && <ResultsPanel result={result} />}{tab === "strategy" && <StrategyPanel result={result} />}{tab === "compare" && <ComparisonPanel result={result} comparison={draft.comparison} />}{tab === "trials" && <TrialsPanel trials={trials} onTrials={onTrials} />}{tab === "reflection" && <ReflectionPanel value={draft.reflection} onChange={onReflection} />}</section>; }
function ResultsPanel({ result }: { result: AuctionResult }) { const winner = result.participants[result.winnerId - 1]; const chartData = result.participants.map((participant) => ({ bidder: `B${participant.id}`, "Private value": participant.value, Bid: participant.bid, "Realised payoff": participant.payoff })); return <div className="mt-5"><section className="rounded-xl border border-[var(--accent)] bg-[var(--accent-soft)] p-5"><p className="text-lg font-bold">Bidder {result.winnerId} wins the item and pays {format(result.payment)} GCU.</p><p className="mt-2 text-sm text-[var(--ink-muted)]">Payment rule: {result.rule === "first-price" ? "the winner pays their own bid" : "the winner pays the second-highest bid"}. Winner value: {format(winner.value)} GCU · Winner surplus: {format(winner.payoff)} GCU.</p></section><PayoffTable result={result} /><div className="mt-5 rounded-xl border border-[var(--line)] bg-[var(--surface)] p-4"><h3 className="text-sm font-bold">Allocation chart</h3><p className="mt-1 text-xs text-[var(--ink-muted)]">Private values, sealed bids and realised payoffs for every bidder (GCU).</p><div className="mt-4 h-[300px]" role="img" aria-label="Grouped chart comparing each bidder's private value, bid and realised payoff"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData}><CartesianGrid stroke="var(--line)" vertical={false}/><XAxis dataKey="bidder" tick={{ fill: "var(--ink-muted)", fontSize: 11 }}/><YAxis tick={{ fill: "var(--ink-muted)", fontSize: 10 }}/><Tooltip contentStyle={{ background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 8, fontSize: 12 }}/><Legend wrapperStyle={{ fontSize: 11 }}/><Bar dataKey="Private value" fill="var(--blue)" radius={[3, 3, 0, 0]}/><Bar dataKey="Bid" fill="var(--accent)" radius={[3, 3, 0, 0]}/><Bar dataKey="Realised payoff" fill="var(--amber)" radius={[3, 3, 0, 0]}/></BarChart></ResponsiveContainer></div></div><MetricCards result={result} /></div>; }
function PayoffTable({ result }: { result: AuctionResult }) { return <div className="mt-5 overflow-x-auto rounded-xl border border-[var(--line)]"><table className="min-w-[720px] w-full text-left text-xs"><thead className="bg-[var(--surface-subtle)] text-[10px] uppercase tracking-wide text-[var(--ink-faint)]"><tr><th className="p-3">Bidder</th><th className="p-3 text-right">Private value</th><th className="p-3 text-right">Bid</th><th className="p-3">Result</th><th className="p-3 text-right">Payment</th><th className="p-3 text-right">Payoff</th></tr></thead><tbody>{result.participants.map((participant) => <tr key={participant.id} className={`border-t border-[var(--line)] ${participant.won ? "bg-[var(--accent-soft)]" : ""}`}><td className="p-3 font-bold">Bidder {participant.id}{participant.id === result.highestValueId && <span className="ml-2 text-[10px] font-normal text-[var(--accent)]">highest value</span>}</td><td className="p-3 text-right">{format(participant.value)}</td><td className="p-3 text-right">{format(participant.bid)}{participant.bid > participant.value && <span className="ml-1 text-[10px] text-[var(--red)]">overbid</span>}</td><td className="p-3 font-semibold">{participant.won ? "Won" : "Lost"}</td><td className="p-3 text-right">{format(participant.payment)}</td><td className={`p-3 text-right font-bold ${participant.payoff < 0 ? "text-[var(--red)]" : ""}`}>{format(participant.payoff)}</td></tr>)}</tbody></table>{result.tieBreakUsed && <p className="border-t border-[var(--line)] px-3 py-2 text-[11px] text-[var(--ink-muted)]">A tied highest bid was settled using the fixed lowest bidder-ID tie-break.</p>}</div>; }
function MetricCards({ result }: { result: AuctionResult }) { const metrics = [{ label: "Allocative efficiency", value: result.allocativeEfficiency.toFixed(2), note: result.allocativeEfficiency ? "The highest-value bidder received the item." : "A bidder without the highest value received the item." }, { label: "Seller revenue", value: `${format(result.sellerRevenue)} GCU`, note: "Payment received under this rule." }, { label: "Winner surplus", value: `${format(result.winnerSurplus)} GCU`, note: "Winner value minus payment." }, { label: "Total bidder surplus", value: `${format(result.totalBidderSurplus)} GCU`, note: "Sum of all bidder payoffs." }, { label: "Fairness Gini", value: result.fairnessGini.toFixed(3), note: "0 indicates equal realised bidder payoffs." }, { label: "Participation rate", value: `${Math.round(result.participationRate * 100)}%`, note: "All configured bidders submitted an action." }, { label: "Profitable ex post deviations", value: String(result.profitableExPostDeviations), note: "Uses information revealed after settlement; not an ex ante optimum." }]; return <div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{metrics.map((metric) => <article key={metric.label} className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-4"><p className="flex items-center gap-1 text-[10px] font-bold uppercase tracking-wide text-[var(--ink-faint)]">{metric.label}<Info size={12} aria-label={metric.note}/></p><p className="mt-2 text-2xl font-bold tracking-[-.04em]">{metric.value}</p><p className="mt-2 text-[11px] leading-4 text-[var(--ink-muted)]">{metric.note}</p></article>)}</div>; }
function StrategyPanel({ result }: { result: AuctionResult }) { return <div className="mt-5 grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><section className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-5"><h3 className="text-lg font-bold">Bid shading and ex post review</h3><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">Ex post analysis uses realised rival bids that were not available before bidding; it does not identify a universally optimal ex ante strategy.</p><div className="mt-5 space-y-3">{result.participants.map((participant) => { const shading = participant.value - participant.bid; const percent = participant.value ? shading / participant.value * 100 : 0; const otherHighest = Math.max(...result.participants.filter((other) => other.id !== participant.id).map((other) => other.bid)); const minimumWinning = otherHighest + 0.01; const couldWin = minimumWinning <= participant.value && !participant.won; return <div key={participant.id} className="rounded-lg bg-[var(--canvas)] p-3 text-xs"><div className="flex justify-between gap-3"><p className="font-bold">Bidder {participant.id}</p><p className="font-semibold text-[var(--accent)]">Shading {format(shading)} GCU ({format(percent)}%)</p></div><p className="mt-2 text-[var(--ink-muted)]">Value {format(participant.value)} · submitted bid {format(participant.bid)} · {participant.won ? "won" : "lost"} · realised payoff {format(participant.payoff)}.</p><p className="mt-1 text-[var(--ink-muted)]">{couldWin ? `Ex post, a bid above ${format(otherHighest)} could have won; this information was hidden at the time.` : "No lower-risk realised winning deviation is identified from the completed bids."}</p></div>; })}</div></section><aside className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-5"><h3 className="text-sm font-bold">Benchmark strategy</h3><p className="mt-3 text-sm leading-6 text-[var(--ink-muted)]">With independent uniform private values, symmetric bidders and risk neutrality, the first-price benchmark is <i>b</i>(<i>v</i>) = ((<i>n</i> − 1)/<i>n</i>)<i>v</i>.</p><p className="mt-4 rounded-lg bg-[var(--surface-subtle)] p-3 text-sm leading-6"><strong>Truthful bidding is not generally a dominant strategy</strong> in a first-price auction.</p><p className="mt-3 text-xs leading-5 text-[var(--ink-muted)]">If the configuration changes the supported distribution, bidder symmetry or risk-neutrality assumption, the standard benchmark no longer applies without further modelling.</p></aside></div>; }
function ComparisonPanel({ result, comparison }: { result: AuctionResult; comparison: AuctionResult | null }) { if (!comparison) return <div className="mt-5 rounded-xl border border-dashed border-[var(--line-strong)] bg-[var(--surface)] p-6"><GitCompareArrows className="text-[var(--accent)]" size={20}/><h3 className="mt-3 text-sm font-bold">No matched comparison in this run</h3><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">Choose Compare Mode before settling to apply the same values, seed and submitted actions under First-Price and Second-Price rules.</p></div>; const first = result.rule === "first-price" ? result : comparison; const second = result.rule === "second-price" ? result : comparison; return <div className="mt-5"><p className="rounded-xl border border-[var(--line)] bg-[var(--surface-subtle)] p-4 text-sm leading-6 text-[var(--ink-muted)]">This is a matched one-run comparison with identical values, participant identities, seed and bids. One run does not establish expected revenue; use repeated trials for that question.</p><div className="mt-4 overflow-x-auto rounded-xl border border-[var(--line)]"><table className="min-w-[660px] w-full text-left text-xs"><thead className="bg-[var(--surface-subtle)] text-[10px] uppercase tracking-wide text-[var(--ink-faint)]"><tr><th className="p-3">Dimension</th><th className="p-3">First-Price Auction</th><th className="p-3">Second-Price Auction</th></tr></thead><tbody>{[["Winner", `Bidder ${first.winnerId}`, `Bidder ${second.winnerId}`], ["Payment", `${format(first.payment)} GCU (own bid)`, `${format(second.payment)} GCU (second-highest bid)`], ["Seller revenue", `${format(first.sellerRevenue)} GCU`, `${format(second.sellerRevenue)} GCU`], ["Allocative efficiency", first.allocativeEfficiency.toFixed(2), second.allocativeEfficiency.toFixed(2)], ["Truthful bidding", "Not generally dominant", "Dominant under standard private-value assumptions"], ["Main strategy issue", "Bid shading", "Value reporting"], ["Manipulability", "Strategy-dependent allocation", "Truthful reporting benchmark"]].map(([dimension, firstValue, secondValue]) => <tr key={dimension} className="border-t border-[var(--line)]"><td className="p-3 font-bold">{dimension}</td><td className="p-3 text-[var(--ink-muted)]">{firstValue}</td><td className="p-3 text-[var(--ink-muted)]">{secondValue}</td></tr>)}</tbody></table></div></div>; }
function TrialsPanel({ trials, onTrials }: { trials: RepeatedAuctionSummary | null; onTrials: (count: 10 | 50 | 100) => void }) { return <div className="mt-5"><section className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-5"><h3 className="text-lg font-bold">Controlled repeated trials</h3><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">Runs use the shared deterministic engine. Compare Mode uses matched seeds under both payment rules; the maximum is deliberately capped at 100 browser runs.</p><div className="mt-4 flex flex-wrap gap-2">{([10, 50, 100] as const).map((count) => <Button key={count} variant="secondary" onClick={() => onTrials(count)}>{count} runs</Button>)}</div></section>{trials && <><div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><TrialMetric label="Mean seller revenue" value={`${format(trials.meanSellerRevenue)} GCU`} /><TrialMetric label="Mean allocative efficiency" value={trials.meanAllocativeEfficiency.toFixed(2)} /><TrialMetric label="Mean winner surplus" value={`${format(trials.meanWinnerSurplus)} GCU`} /><TrialMetric label="Mean bid shading" value={`${format(trials.meanBidShading)} GCU`} /><TrialMetric label="Inefficient allocation frequency" value={`${Math.round(trials.inefficientAllocationFrequency * 100)}%`} /><TrialMetric label="Matched second-price revenue" value={`${format(trials.secondPriceRevenue)} GCU`} /></div><div className="mt-5 rounded-xl border border-[var(--line)] bg-[var(--surface)] p-4"><h4 className="text-sm font-bold">Revenue distribution across matched seeds</h4><div className="mt-4 h-[300px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={trials.revenueSeries}><CartesianGrid stroke="var(--line)" vertical={false}/><XAxis dataKey="run" tick={{ fill: "var(--ink-muted)", fontSize: 10 }}/><YAxis tick={{ fill: "var(--ink-muted)", fontSize: 10 }}/><Tooltip contentStyle={{ background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 8, fontSize: 12 }}/><Legend wrapperStyle={{ fontSize: 11 }}/><Line type="monotone" dataKey="firstPrice" name="First-price revenue" stroke="var(--accent)" dot={false}/><Line type="monotone" dataKey="secondPrice" name="Second-price revenue" stroke="var(--blue)" dot={false}/></LineChart></ResponsiveContainer></div></div></>}</div>; }
function TrialMetric({ label, value }: { label: string; value: string }) { return <article className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-4"><p className="text-[10px] font-bold uppercase tracking-wide text-[var(--ink-faint)]">{label}</p><p className="mt-2 text-2xl font-bold tracking-[-.04em]">{value}</p></article>; }
function ReflectionPanel({ value, onChange }: { value: string; onChange: (value: string) => void }) { const prompts = ["Why might bidders shade their bids?", "Did the highest-value bidder win, and was the allocation efficient?", "Who benefited from the payment rule?", "How might the result differ under a second-price auction?", "Is one run sufficient to compare expected revenue?"]; return <div className="mt-5 grid gap-5 lg:grid-cols-[.85fr_1.15fr]"><section className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-5"><h3 className="text-sm font-bold">Reflection prompts</h3><ol className="mt-4 space-y-3 text-sm leading-6 text-[var(--ink-muted)]">{prompts.map((prompt, index) => <li key={prompt}><span className="mr-2 font-bold text-[var(--accent)]">{index + 1}.</span>{prompt}</li>)}</ol><p className="mt-4 text-xs leading-5 text-[var(--ink-faint)]">Reflection is saved with the experiment draft and is not graded by AI.</p></section><label className="rounded-xl border border-[var(--line)] bg-[var(--surface)] p-5 text-sm font-bold">Your reflection<textarea value={value} onChange={(event) => onChange(event.target.value)} placeholder="Write a short explanation using the result and the stated assumptions…" className="mt-3 min-h-52 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] p-3 text-sm font-normal leading-6 outline-none focus:border-[var(--accent)]"/></label></div>; }

function ExperimentReport({ scenario, draft }: { scenario: MechanismScenario; draft: AuctionDraft }) { const result = draft.result; return <article className="mechanism-experiment-report"><h1>{scenario.title}</h1><p>{scenario.scenario_id} · version 1.0.0 · generated {new Date().toLocaleString()}</p>{result ? <><h2>Run record</h2><p>Seed {draft.seed} · {draft.mode} mode · {draft.parameters.bidderCount} bidders · {distributionLabels[draft.parameters.distribution]} distribution.</p><h2>Allocation and payoffs</h2><table><thead><tr><th>Bidder</th><th>Value</th><th>Bid</th><th>Result</th><th>Payment</th><th>Payoff</th></tr></thead><tbody>{result.participants.map((participant) => <tr key={participant.id}><td>Bidder {participant.id}</td><td>{format(participant.value)}</td><td>{format(participant.bid)}</td><td>{participant.won ? "Won" : "Lost"}</td><td>{format(participant.payment)}</td><td>{format(participant.payoff)}</td></tr>)}</tbody></table><h2>Metrics</h2><p>Allocative efficiency {result.allocativeEfficiency.toFixed(2)} · Seller revenue {format(result.sellerRevenue)} GCU · Winner surplus {format(result.winnerSurplus)} GCU · Fairness Gini {result.fairnessGini.toFixed(3)}.</p><h2>Strategy analysis</h2><p>Bid shading is private value minus submitted bid. Ex post deviations use information only revealed after settlement.</p>{draft.comparison && <><h2>Matched comparison</h2><p>First-price and second-price results used the same values, seed and submitted actions.</p></>}{draft.reflection && <><h2>Reflection</h2><p>{draft.reflection}</p></>}</> : <p>No settlement has been completed for this report.</p>}</article>; }
